"""Core-owned recovery classifications and settled read-only failure proofs."""

import hashlib
import json

from .governance import parameter_digest


def provider_failure_code(exc):
    from .providers import ProviderError

    if isinstance(exc, TimeoutError):
        return "timeout"
    allowed = {
        "auth",
        "rate_limit",
        "budget_exhausted",
        "budget_unconfigured",
        "configuration",
        "context_exceeded",
        "network",
        "protocol_error",
        "provider_error",
        "refused",
        "timeout",
        "truncated",
        "unsupported",
        "attempt_unknown",
        "concurrency_unavailable",
    }
    return (
        exc.code
        if isinstance(exc, ProviderError) and exc.code in allowed
        else "unexpected_provider_error"
    )


def provider_exception_type(exc):
    """Fixed diagnostic labels; never persist remote text or custom class names."""
    from .domain import DomainError
    from .providers import ProviderError

    for exception_type in (
        ProviderError,
        DomainError,
        TimeoutError,
        TypeError,
        ValueError,
        KeyError,
        RuntimeError,
        OSError,
    ):
        if isinstance(exc, exception_type):
            return exception_type.__name__
    return "UnexpectedError"


def failure_category(reason):
    if reason in {
        "invalid_output_contract",
        "invalid_model_output",
        "incomplete_model_output",
        "model_truncated",
    }:
        return "task_contract"
    if reason in {"provider_unavailable", "provider_mode_changed", "model_error", "usage_unknown"}:
        return "provider"
    if reason in {
        "context_budget",
        "step_budget",
        "tool_budget",
        "token_budget",
        "cost_budget",
        "deadline",
    }:
        return "budget"
    if reason == "approval_required":
        return "authorization"
    if reason in {"help_requested", "help_request_rejected"}:
        return "dependency"
    if reason in {"python_compile_failed", "numeric_ast_failed", "python_test_failed"}:
        return "code"
    if reason == "resource_unavailable":
        return "external_resource"
    if reason.startswith("tool_") or reason == "unresolved_tool_recovery":
        return "tool"
    return "runtime"


def settled_read_failure(connection, run_id, call, *, require_repair=True):
    """A failed local diagnostic is observable, not an uncertain external action.

    This never authorizes replay. A new model-selected call must have a new ID,
    and the failed call, receipt and recovery event remain in the audit history.
    """
    try:
        if call["state"] == "failed" and call["receipt_id"] is None:
            return settled_preexecution_rejection(connection, run_id, call)
        if call["state"] != "failed" or call["tool_name"] not in {
            "shell_inspect",
            "python_compile",
            "numeric_ast",
            "python_test",
            "git_status",
            "file_read",
            "directory_list",
        }:
            return False
        row = connection.execute(
            """SELECT r.*,i.run_id,i.call_id,i.tool_name,i.parameters_json,
            i.parameter_digest,i.state,i.risk,i.execution_mode AS intent_mode
            FROM action_receipts r JOIN action_intents i ON i.id=r.intent_id
            WHERE r.id=? AND i.run_id=?""",
            (call["receipt_id"], run_id),
        ).fetchone()
        result = json.loads(call["result_json"])
        if (
            row is None
            or row["state"] != "failed"
            or row["risk"] != "R0"
            or row["call_id"] != call["call_id"]
            or row["tool_name"] != call["tool_name"]
            or row["execution_mode"] != row["intent_mode"]
            or parameter_digest(json.loads(row["parameters_json"])) != row["parameter_digest"]
            or parameter_digest(json.loads(call["arguments_json"])) != row["parameter_digest"]
            or hashlib.sha256(row["result_json"].encode("utf-8")).hexdigest()
            != row["result_digest"]
            or result.get("call_id") != row["call_id"]
            or result.get("receipt_id") != row["id"]
            or result.get("intent_id") != row["intent_id"]
            or result.get("state") != "failed"
            or result.get("output") != json.loads(row["result_json"])
        ):
            return False
        if not require_repair:
            return True
        return (
            connection.execute(
                """SELECT 1 FROM events WHERE event_type='worker.progress'
            AND json_extract(payload,'$.run_id')=?
            AND json_extract(payload,'$.phase')='self_repair'
            AND json_extract(payload,'$.failed_call_id')=?
            AND json_extract(payload,'$.receipt_id')=? LIMIT 1""",
                (run_id, call["call_id"], row["id"]),
            ).fetchone()
            is not None
        )
    except (TypeError, ValueError, KeyError, IndexError):
        return False


def settled_preexecution_rejection(connection, run_id, call):
    """Verify Core's pre-execution R0 denial without inventing a receipt."""
    try:
        from .tool_domain import CONTRACTS

        contract = next(item for item in CONTRACTS if item.name == call["tool_name"])
        if contract.risk != "R0" or call["state"] != "failed" or call["receipt_id"] is not None:
            return False
        result = json.loads(call["result_json"])
        if (
            result.get("state") != "rejected_before_execution"
            or result.get("call_id") != call["call_id"]
        ):
            return False
        if connection.execute(
            "SELECT 1 FROM action_intents WHERE call_id=?", (call["call_id"],)
        ).fetchone():
            return False
        event = connection.execute(
            "SELECT payload FROM events WHERE event_type='worker.progress' "
            "AND json_extract(payload,'$.run_id')=? AND json_extract(payload,'$.phase')='self_repair' "
            "AND json_extract(payload,'$.failed_call_id')=? AND json_extract(payload,'$.no_effect')=1 ORDER BY seq DESC LIMIT 1",
            (run_id, call["call_id"]),
        ).fetchone()
        if event is None or json.loads(event[0]).get("parameter_digest") != parameter_digest(
            json.loads(call["arguments_json"])
        ):
            return False
        messages = connection.execute(
            "SELECT message_json FROM worker_messages WHERE run_id=? AND role='tool'", (run_id,)
        ).fetchall()
        return any(
            (item := json.loads(row[0])).get("tool_call_id") == call["model_call_id"]
            and json.loads(item["content"]).get("state") == "rejected_before_execution"
            for row in messages
        )
    except (StopIteration, TypeError, ValueError, KeyError, IndexError):
        return False


def unresolved_calls(connection, run_id):
    from .worker_prefetch import unresolved_sources

    return (
        [
            row
            for row in connection.execute(
                "SELECT * FROM worker_tool_calls WHERE run_id=? AND state IN ('running','uncertain','failed')",
                (run_id,),
            )
            if not settled_read_failure(connection, run_id, row)
        ]
        + unresolved_sources(connection, run_id)
        + list(
            connection.execute(
                "SELECT * FROM worker_model_reservations WHERE run_id=? AND state='reserved' "
                "AND json_extract(context_json,'$.purpose')='context_compaction'",
                (run_id,),
            )
        )
    )
"""Durable at-least-once, per-consumer local event delivery.

Only trusted Core code may register handlers. A handler participates in the same
SQLite transaction and must not perform external side effects.
"""

import json
import math
import re
import secrets
import time
from dataclasses import asdict

from .agent_protocol import COORDINATION_EVENTS, AgentMessage
from .domain import DomainError
from .event_domain import URGENT_EVENTS, WORKER_COMMANDS, WORKER_FACTS, DeliveryLease, EventEnvelope

_URGENT_PLACEHOLDERS = ",".join("?" for _ in URGENT_EVENTS)


class LeaseError(RuntimeError):
    pass


class Dispatcher:
    def __init__(
        self, store, *, clock=time.time, lease_seconds=30, max_attempts=5, base_backoff_seconds=1
    ):
        if type(max_attempts) is not int or not 1 <= max_attempts <= 100:
            raise ValueError("Invalid delivery attempts")
        if any(
            type(x) not in (float, int) or not math.isfinite(x) or x <= 0
            for x in (lease_seconds, base_backoff_seconds)
        ):
            raise ValueError("Invalid delivery timing")
        self.store, self.clock = store, clock
        self.lease_seconds, self.max_attempts, self.base_backoff_seconds = (
            lease_seconds,
            max_attempts,
            base_backoff_seconds,
        )
        self._worker_cursor = ""
        self._consumer_cursor = 0

    def _now(self):
        now = self.clock()
        if type(now) not in (float, int) or not math.isfinite(now):
            raise ValueError("Invalid clock value")
        return float(now)

    def register(self, consumer_id, *, kind="router", worker_id=None, replay_from_seq=0):
        if (
            not isinstance(consumer_id, str)
            or not consumer_id
            or len(consumer_id) > 256
            or type(replay_from_seq) is not int
            or replay_from_seq < 0
        ):
            raise ValueError("Invalid consumer")
        if (
            kind not in {"router", "worker"}
            or (kind == "router" and worker_id is not None)
            or (kind == "worker" and (not isinstance(worker_id, str) or not worker_id))
        ):
            raise ValueError("Invalid consumer kind")
        with self.store.unit_of_work() as work:
            connection = work.connection
            old = connection.execute(
                "SELECT * FROM event_consumers WHERE id=?", (consumer_id,)
            ).fetchone()
            if old is not None:
                if (old["kind"], old["worker_id"], old["replay_from_seq"]) != (
                    kind,
                    worker_id,
                    replay_from_seq,
                ):
                    raise ValueError("Consumer registration differs from existing subscription")
                return
            connection.execute(
                "INSERT INTO event_consumers VALUES (?,?,?,?,?,?,?)",
                (
                    consumer_id,
                    kind,
                    worker_id,
                    replay_from_seq,
                    replay_from_seq,
                    replay_from_seq,
                    replay_from_seq,
                ),
            )

    @staticmethod
    def _materialize(connection, consumer_id):
        consumer = connection.execute(
            "SELECT scan_seq,priority_scan_seq FROM event_consumers WHERE id=?", (consumer_id,)
        ).fetchone()
        rows = connection.execute(
            "SELECT id,seq FROM events WHERE seq>? ORDER BY seq LIMIT 100", (consumer["scan_seq"],)
        ).fetchall()
        connection.executemany(
            "INSERT OR IGNORE INTO event_deliveries(consumer_id,event_id,seq,state) VALUES (?,?,?,'pending')",
            [(consumer_id, row["id"], row["seq"]) for row in rows],
        )
        if rows:
            connection.execute(
                "UPDATE event_consumers SET scan_seq=? WHERE id=?", (rows[-1]["seq"], consumer_id)
            )
        urgent = connection.execute(
            f"""SELECT e.id,e.seq FROM events e WHERE e.seq>? AND e.event_type IN
            ({_URGENT_PLACEHOLDERS}) ORDER BY e.seq LIMIT 16""",
            (consumer["priority_scan_seq"], *URGENT_EVENTS),
        ).fetchall()
        connection.executemany(
            "INSERT OR IGNORE INTO event_deliveries(consumer_id,event_id,seq,state) VALUES (?,?,?,'pending')",
            [(consumer_id, row["id"], row["seq"]) for row in urgent],
        )
        if urgent:
            connection.execute(
                "UPDATE event_consumers SET priority_scan_seq=? WHERE id=?",
                (urgent[-1]["seq"], consumer_id),
            )

    @staticmethod
    def _advance(connection, consumer_id, seq):
        scan = connection.execute(
            "SELECT scan_seq FROM event_consumers WHERE id=?", (consumer_id,)
        ).fetchone()[0]
        gap = connection.execute(
            "SELECT MIN(seq) FROM event_deliveries WHERE consumer_id=? AND state IN ('pending','leased')",
            (consumer_id,),
        ).fetchone()[0]
        if gap is None:
            last = connection.execute(
                "SELECT MAX(seq) FROM event_deliveries WHERE consumer_id=?", (consumer_id,)
            ).fetchone()[0]
        else:
            last = connection.execute(
                "SELECT MAX(seq) FROM event_deliveries WHERE consumer_id=? AND seq<? AND state IN ('delivered','dead','skipped')",
                (consumer_id, gap),
            ).fetchone()[0]
        if last is not None:
            connection.execute(
                "UPDATE event_consumers SET cursor_seq=MAX(cursor_seq,?) WHERE id=?",
                (min(last, scan), consumer_id),
            )

    @staticmethod
    def _routable(connection, consumer, row):
        is_command = row["event_type"].startswith("worker.command.")
        if consumer["id"] == "planner" and consumer["kind"] == "router":
            return row["event_type"] in {
                "quest.proposed",
                "quest.proposal_updated",
                "quest.replan_requested",
            }
        if consumer["id"] == "composer" and consumer["kind"] == "router":
            return row["event_type"] in {"quest.plan_approved", "worker.help_requested"}
        if consumer["kind"] == "worker":
            worker = connection.execute(
                "SELECT status FROM workers WHERE id=?", (consumer["worker_id"],)
            ).fetchone()
            return bool(
                worker
                and worker["status"] not in {"completed", "failed", "cancelled", "rejected"}
                and row["event_type"] in WORKER_COMMANDS
                and row["worker_id"] == consumer["worker_id"]
            )
        return not is_command

    def claim(self, consumer_id):
        with self.store.unit_of_work() as work:
            now = self._now()
            connection = work.connection
            consumer = connection.execute(
                "SELECT * FROM event_consumers WHERE id=?", (consumer_id,)
            ).fetchone()
            if consumer is None:
                raise KeyError(consumer_id)
            self._materialize(connection, consumer_id)
            while True:
                row = connection.execute(
                    """SELECT d.*,e.event_type,e.worker_id FROM event_deliveries d
                    JOIN events e ON e.id=d.event_id WHERE d.consumer_id=? AND d.state IN ('pending','leased')
                    ORDER BY d.seq LIMIT 1""",
                    (consumer_id,),
                ).fetchone()
                if row is None:
                    return None
                urgent = connection.execute(
                    f"""SELECT d.*,e.event_type,e.worker_id FROM event_deliveries d
                    JOIN events e ON e.id=d.event_id WHERE d.consumer_id=?
                    AND e.event_type IN ({_URGENT_PLACEHOLDERS})
                    AND ((d.state='pending' AND d.next_attempt<=?) OR (d.state='leased' AND d.lease_until<=?))
                    ORDER BY d.seq LIMIT 1""",
                    (consumer_id, *URGENT_EVENTS, now, now),
                ).fetchone()
                if urgent is not None:
                    row = urgent
                if not self._routable(connection, consumer, row):
                    connection.execute(
                        "UPDATE event_deliveries SET state='skipped' WHERE consumer_id=? AND event_id=?",
                        (consumer_id, row["event_id"]),
                    )
                    self._advance(connection, consumer_id, row["seq"])
                    continue
                if row["state"] == "leased" and row["lease_until"] > now:
                    return None
                if row["state"] == "pending" and row["next_attempt"] > now:
                    return None
                if row["attempts"] >= self.max_attempts:
                    connection.execute(
                        "UPDATE event_deliveries SET state='dead',lease_token=NULL,lease_until=NULL,last_error='lease_expired' WHERE consumer_id=? AND event_id=?",
                        (consumer_id, row["event_id"]),
                    )
                    self._advance(connection, consumer_id, row["seq"])
                    continue
                token = secrets.token_hex(32)
                attempt = row["attempts"] + 1
                connection.execute(
                    "UPDATE event_deliveries SET state='leased',lease_token=REDACTED,lease_until=?,attempts=? WHERE consumer_id=? AND event_id=?",
                    (token, now + self.lease_seconds, attempt, consumer_id, row["event_id"]),
                )
                return DeliveryLease(consumer_id, row["event_id"], row["seq"], token, attempt)

    def _leased(self, connection, lease, now):
        if not isinstance(lease, DeliveryLease):
            raise LeaseError("Invalid delivery lease")
        row = connection.execute(
            """SELECT d.*,e.event_type,e.conversation_id,e.quest_id,e.worker_id,e.payload
            FROM event_deliveries d JOIN events e ON e.id=d.event_id
            WHERE d.consumer_id=? AND d.event_id=?""",
            (lease.consumer_id, lease.event_id),
        ).fetchone()
        if (
            row is None
            or row["state"] != "leased"
            or row["lease_token"] != lease.token
            or row["lease_until"] <= now
            or row["seq"] != lease.seq
            or row["attempts"] != lease.attempt
        ):
            raise LeaseError("Delivery lease is stale")
        return row

    @staticmethod
    def _agent_protocol(connection, row, payload):
        if row["event_type"] not in COORDINATION_EVENTS:
            return {}
        native = any(name in payload for name in ("run_id", "plan_id", "task_node_key"))
        if not native:
            return {"execution_protocol": "legacy_nonexecution", "agent_message": None}
        try:
            event = {**dict(row), "id": row["event_id"]}
            message = AgentMessage.from_event(event, payload)
            run_id = payload.get("run_id")
            if run_id is not None and (not isinstance(run_id, str) or not 1 <= len(run_id) <= 256):
                raise ValueError("Invalid Agent run identity")
            run = connection.execute(
                "SELECT * FROM worker_runs WHERE worker_id=? AND quest_id=? AND plan_id=? AND node_key=? "
                + ("AND id=?" if run_id is not None else "ORDER BY created_at DESC LIMIT 1"),
                (
                    message.sender_id if message.receiver_id == "router" else message.receiver_id,
                    message.quest_id,
                    message.plan_id,
                    message.task_node_key,
                    *([run_id] if run_id is not None else []),
                ),
            ).fetchone()
            if (
                run is None
                or payload.get("message_type", message.message_type) != message.message_type
            ):
                raise ValueError("Agent protocol association does not match a native assignment")
            return {"execution_protocol": "native", "agent_message": asdict(message)}
        except (DomainError, TypeError, KeyError) as exc:
            raise ValueError("Invalid native Agent protocol envelope") from exc

    def deliver(self, lease, *, handler=None):
        with self.store.unit_of_work() as work:
            now = self._now()
            connection = work.connection
            row = self._leased(connection, lease, now)
            try:
                payload = json.loads(row["payload"])
            except (ValueError, TypeError):
