            assert "read_trigger" in {tool["name"] for tool in request.tools}
            return ModelResponse(
                text="",
                tool_calls=[
                    {
                        "id": "read-original",
                        "name": "read_trigger",
                        "arguments": {
                            "trigger_id": trigger["id"],
                            "offset_chars": 2900,
                            "max_chars": 1024,
                        },
                    }
                ],
                usage={"input_tokens": 10, "output_tokens": 5},
            )
        tool = request.messages[-1]
